-- Read-only audit for Supabase E2E. Do not run against production.
select ns.nspname as table_schema, cls.relname as table_name, trg.tgname as trigger_name, case trg.tgenabled when 'O' then 'enabled' when 'D' then 'disabled' when 'R' then 'replica' when 'A' then 'always' end as enabled, case when (trg.tgtype & 2)=2 then 'BEFORE' when (trg.tgtype & 64)=64 then 'INSTEAD OF' else 'AFTER' end as timing, concat_ws(',', case when (trg.tgtype & 4)=4 then 'INSERT' end, case when (trg.tgtype & 8)=8 then 'DELETE' end, case when (trg.tgtype & 16)=16 then 'UPDATE' end, case when (trg.tgtype & 32)=32 then 'TRUNCATE' end) as events, case when (trg.tgtype & 1)=1 then 'ROW' else 'STATEMENT' end as orientation, pg_get_expr(trg.tgqual,trg.tgrelid) as condition, format('%I.%I(%s)',fn_ns.nspname,fn.proname,pg_get_function_identity_arguments(fn.oid)) as function_signature, pg_get_triggerdef(trg.oid) as trigger_definition from pg_trigger trg join pg_class cls on cls.oid=trg.tgrelid join pg_namespace ns on ns.oid=cls.relnamespace join pg_proc fn on fn.oid=trg.tgfoid join pg_namespace fn_ns on fn_ns.oid=fn.pronamespace where not trg.tgisinternal and ns.nspname='public' order by cls.relname,trg.tgname;
